    Jelaskan alasan Anda.
\item
    Tanpa benar-benar menghitung intervalnya, tentukan
    apakah dugaan peneliti pada
    bagian~(\ref{cyberbullying_prop_ci_ht_researcher})
    akan didukung berdasarkan interval kepercayaan 90\%.
\end{parts}
