\begin{align*}
& P(n=4\text{ ATAU }n=5) = P(n=4) + P(n=5) \\
&\quad = {4-1 \choose 4-1} 0.8^4 + {5-1 \choose 4-1} (0.8)^4(1-0.8) = 1\times 0.41 + 4\times 0.082 = 0.41 + 0.33 = 0.74
\end{align*}}

\footnotetext{(a)~$N(\mu=5,\sigma=3)$.
